package com.tapeverify.copilot.entity; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="reviewer_actions") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class ReviewerAction {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="loan_id",nullable=false) private Loan loan; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="exception_id") private ValidationException exception; @Column(nullable=false,length=32) private String action; @Lob @Column(name="comment_text",columnDefinition="TEXT") private String commentText; @Column(nullable=false) private String actor; @Column(name="created_at",nullable=false) private LocalDateTime createdAt;}
